SET documentdb.document_toast_compression_threshold TO 1024;

SELECT document FROM bson_aggregation_find('doc_size_db', '{ "find": "doc_size_upsert", "projection": { "f01abcdefghijkl": 1 }, "sort": { "_id": 1 } }');

SELECT documentdb_api.drop_collection('doc_size_db', 'doc_size_upsert');

-- Raw writes through a test function that compresses the document. The
-- function is volatile so the planner does not fold it into a constant.
CREATE FUNCTION documentdb_api_internal.test_compress_bson_if_needed(documentdb_core.bson)
RETURNS documentdb_core.bson LANGUAGE C STRICT AS 'pg_documentdb', $$test_compress_bson_if_needed$$;

SELECT documentdb_api.create_collection('doc_size_db', 'doc_size_raw');

-- A raw insert of the document as is is stored uncompressed.
WITH d AS (SELECT '{"_id": "rawinsertplainabcdefghijklmnopqrstu", "f01abcdefghijkl": "opqrstu", "f02abcde": "vwxyz0123456789abcdefghijklmnopqrstu", "f03abcdefghijk": {"f04abcd": "23456789abcdefghijklmnopqrstuvwxyz0123456789", "f05a": "9abcdefghijklmnopqrstuvw", "f06ab": "ghijklmnopqrstuvwxyz0123", "f07abcd": "nopqrstuvwxyz0123456789a"}, "f08abcdefghi": ["uvwxyz0123456789abcdefgh"], "f09abcd": "12", "f10abcdef": {"$date": {"$numberLong": "1700000010000"}}, "f11abcdefghijklmn": "fghijklmnopqrs", "f12abcd": true, "f13abcdefghijkl": {"f04abcd": "mnopqrstuvwxyz0123456789abcdefghijklmnopqrst", "f05a": "tuvwxyz0123456789abcdefg", "f06ab": "0123456789abcdefghijklmn", "f07abcd": "789abcdefghijklmnopqrstu"}, "f14abcdefghijklm": "efgh", "f15abcdefghijklmno": "lmno", "f16abcdefghijk": true, "f17abcdefghi": true, "f18abcdefghijklmnopqrs": true, "f19abcdefghi": true, "f20abcdefghij": [], "f21abcdefghi": {"f22a": "stuvwxyz012", "f23ab": "z01"}, "f24a": "6789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwx", "f25ab": {"f26abcdef": "defghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz01234", "f27ab": "klmnopqrstuvwxyz01234567"}, "f28abcdefghijk": ["rstuvwxyz"], "f29abcdefghi": [{"f22a": "yz0123456", "f30abcdefgh": [{"f31a": {"$numberInt": "25"}}]}], "f32abcdefghijkl": [], "f33abcdefghijklmnop": {"f24a": "cdefghijklmnop"}, "f34abc": "jklmnop", "f35ab": "qrstuvwxyz0123456789abcd", "f36abcdef": {"$date": {"$numberLong": "1700000029000"}}, "f37ab": true, "f38abcdefghij": {"$date": {"$numberLong": "1700000030000"}}, "f39abcdefgh": "bcdefghijklmnopqrstuvwxyz0123456789abcdef", "f40abc": {"f41abcd": "i", "f42abcd": "p", "f43abcdef": "wxyz", "f44ab": "3456", "f36abcdef": {"$date": {"$numberLong": "1700000036000"}}, "f12abcd": true, "f45abcdefgh": "h"}}'::documentdb_core.bson AS document)
INSERT INTO documentdb_data.documents_27140004 (shard_key_value, object_id, document)
SELECT 27140004, bson_get_value(document, '_id'), document FROM d;

-- A raw insert through the function is stored compressed.
WITH d AS (SELECT '{"_id": "rawinsertcompressedabcdefghijklmno", "f01abcdefghijkl": "opqrstu", "f02abcde": "vwxyz0123456789abcdefghijklmnopqrstu", "f03abcdefghijk": {"f04abcd": "23456789abcdefghijklmnopqrstuvwxyz0123456789", "f05a": "9abcdefghijklmnopqrstuvw", "f06ab": "ghijklmnopqrstuvwxyz0123", "f07abcd": "nopqrstuvwxyz0123456789a"}, "f08abcdefghi": ["uvwxyz0123456789abcdefgh"], "f09abcd": "12", "f10abcdef": {"$date": {"$numberLong": "1700000010000"}}, "f11abcdefghijklmn": "fghijklmnopqrs", "f12abcd": true, "f13abcdefghijkl": {"f04abcd": "mnopqrstuvwxyz0123456789abcdefghijklmnopqrst", "f05a": "tuvwxyz0123456789abcdefg", "f06ab": "0123456789abcdefghijklmn", "f07abcd": "789abcdefghijklmnopqrstu"}, "f14abcdefghijklm": "efgh", "f15abcdefghijklmno": "lmno", "f16abcdefghijk": true, "f17abcdefghi": true, "f18abcdefghijklmnopqrs": true, "f19abcdefghi": true, "f20abcdefghij": [], "f21abcdefghi": {"f22a": "stuvwxyz012", "f23ab": "z01"}, "f24a": "6789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwx", "f25ab": {"f26abcdef": "defghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz01234", "f27ab": "klmnopqrstuvwxyz01234567"}, "f28abcdefghijk": ["rstuvwxyz"], "f29abcdefghi": [{"f22a": "yz0123456", "f30abcdefgh": [{"f31a": {"$numberInt": "25"}}]}], "f32abcdefghijkl": [], "f33abcdefghijklmnop": {"f24a": "cdefghijklmnop"}, "f34abc": "jklmnop", "f35ab": "qrstuvwxyz0123456789abcd", "f36abcdef": {"$date": {"$numberLong": "1700000029000"}}, "f37ab": true, "f38abcdefghij": {"$date": {"$numberLong": "1700000030000"}}, "f39abcdefgh": "bcdefghijklmnopqrstuvwxyz0123456789abcdef", "f40abc": {"f41abcd": "i", "f42abcd": "p", "f43abcdef": "wxyz", "f44ab": "3456", "f36abcdef": {"$date": {"$numberLong": "1700000036000"}}, "f12abcd": true, "f45abcdefgh": "h"}}'::documentdb_core.bson AS document)
